import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { auth } from './firebaseConfig';
import * as api from './services/api';
import { Resource, Lead } from './types';

import { Header } from './components/Header';
import { BottomNav } from './components/BottomNav';
import Footer from './components/Footer';
import HomePage from './pages/HomePage';
import AdminPage from './pages/AdminPage';
import LoginPage from './pages/LoginPage';
import ResourcePage from './pages/ResourcePage';
import EmbedResourcePage from './pages/EmbedResourcePage';
import PrivacyPolicyPage from './pages/PrivacyPolicyPage';
import ProtectedRoute from './components/ProtectedRoute';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [resources, setResources] = useState<Resource[]>([]);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Auth State Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setIsLoading(false);
    });
    return unsubscribe;
  }, []);

  // Data Fetching logic
  const fetchData = useCallback(async () => {
    try {
      const fetchedResources = await api.getResources();
      setResources(fetchedResources);

      // Only fetch leads if admin is logged in
      if (auth.currentUser) {
        const fetchedLeads = await api.getLeads();
        setLeads(fetchedLeads);
      }
    } catch (error) {
      console.error("Failed to fetch data:", error);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData, user]);

  const handleLogin = async (email: string, pass: string) => {
    return await api.login(email, pass);
  };

  const handleLogout = async () => {
    await api.logout();
  };

  const handleAddResource = async (resource: Omit<Resource, 'id' | 'downloadCount'>, file?: File) => {
    await api.addResource(resource, file);
    await fetchData();
  };

  const handleUpdateResource = async (resource: Resource, file?: File) => {
    await api.updateResource(resource, file);
    await fetchData();
  };

  const handleDeleteResource = async (id: string) => {
    const resource = resources.find(r => r.id === id);
    if (resource) {
      await api.deleteResource(id, resource);
      await fetchData();
    }
  };

  const handleDownload = async (resourceId: string, leadData: { firstName: string; email: string; hasConsented: boolean }) => {
    const resource = resources.find(r => r.id === resourceId);
    if (resource) {
      // Record the lead / increment counter
      await api.addLead(resourceId, resource.title, leadData);

      // If it's not a "Coming Soon" item and has a file, trigger download
      if (!resource.isComingSoon && resource.fileUrl) {
        window.open(resource.fileUrl, '_blank');
      }

      await fetchData();
    }
  };

  const handleGoogleDriveClick = async (resourceId: string) => {
    await api.incrementResourceAccessCount(resourceId);
    await fetchData();
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-background-light">
        <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate font-medium">Loading Library...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <div className="flex flex-col min-h-screen">
        <Header isAuthenticated={!!user} onLogout={handleLogout} />

        <main className="flex-grow pb-20 md:pb-0">
          <Routes>
            <Route 
              path="/" 
              element={
                <HomePage 
                  resources={resources} 
                  onDownload={handleDownload} 
                  onGoogleDriveClick={handleGoogleDriveClick} 
                />
              } 
            />
            <Route 
              path="/resource/:id" 
              element={
                <ResourcePage 
                  resources={resources} 
                  onDownload={handleDownload} 
                />
              } 
            />
            <Route 
              path="/embed/:id" 
              element={
                <EmbedResourcePage 
                  resources={resources} 
                  onDownload={handleDownload} 
                  onGoogleDriveClick={handleGoogleDriveClick} 
                />
              } 
            />
            <Route 
              path="/login" 
              element={<LoginPage onLogin={handleLogin} />} 
            />
            <Route 
              path="/privacy" 
              element={<PrivacyPolicyPage />} 
            />
            <Route 
              path="/admin" 
              element={
                <ProtectedRoute isAuthenticated={!!user}>
                  <AdminPage 
                    resources={resources} 
                    leads={leads}
                    addResource={handleAddResource}
                    updateResource={handleUpdateResource}
                    deleteResource={handleDeleteResource}
                    adminUsername={user?.email || ''}
                    updateCredentials={api.updateCredentials}
                  />
                </ProtectedRoute>
              } 
            />
            {/* Redirect any unknown routes to home */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>

        <Footer isAuthenticated={!!user} />
        <BottomNav isAuthenticated={!!user} onLogout={handleLogout} />
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useEffect } from 'react';
import { Resource } from '../types';

interface SEOProps {
  title: string;
  description: string;
  resource?: Resource;
  resources?: Resource[];
  type?: 'website' | 'article' | 'collection';
}

const SEO: React.FC<SEOProps> = ({ title, description, resource, resources, type = 'website' }) => {
  const siteName = "BP Money Financial Resource Library";
  const fullTitle = `${title} | ${siteName}`;
  const url = window.location.href;

  useEffect(() => {
    // Update basic meta tags
    document.title = fullTitle;

    const updateMeta = (name: string, content: string, attr: 'name' | 'property' = 'name') => {
      let el = document.querySelector(`meta[${attr}="${name}"]`);
      if (!el) {
        el = document.createElement('meta');
        el.setAttribute(attr, name);
        document.head.appendChild(el);
      }
      el.setAttribute('content', content);
    };

    updateMeta('description', description);

    // Open Graph
    updateMeta('og:title', fullTitle, 'property');
    updateMeta('og:description', description, 'property');
    updateMeta('og:type', type, 'property');
    updateMeta('og:url', url, 'property');
    updateMeta('og:site_name', siteName, 'property');

    // Twitter
    updateMeta('twitter:card', 'summary_large_image');
    updateMeta('twitter:title', fullTitle);
    updateMeta('twitter:description', description);

    // Schema Markup (JSON-LD)
    let schemaData: any = null;

    if (resource) {
      // Single Resource Schema
      schemaData = {
        "@context": "https://schema.org",
        "@type": "CreativeWork",
        "name": resource.title,
        "description": resource.description,
        "genre": resource.category,
        "keywords": (resource.tags || []).join(', '),
        "image": resource.imageUrl,
        "author": {
          "@type": "Organization",
          "name": "BiggerPockets Money"
        },
        "publisher": {
          "@type": "Organization",
          "name": "BiggerPockets Money",
          "logo": {
            "@type": "ImageObject",
            "url": "https://www.biggerpockets.com/assets/logo.png"
          }
        }
      };
    } else if (resources) {
      // Collection Schema for Home Page
      schemaData = {
        "@context": "https://schema.org",
        "@type": "CollectionPage",
        "name": siteName,
        "description": description,
        "mainEntity": {
          "@type": "ItemList",
          "itemListElement": resources.map((res, index) => ({
            "@type": "ListItem",
            "position": index + 1,
            "url": `${window.location.origin}/#/resource/${res.id}`,
            "name": res.title
          }))
        }
      };
    } else {
      // Default Website Schema
      schemaData = {
        "@context": "https://schema.org",
        "@type": "WebSite",
        "name": siteName,
        "url": window.location.origin,
        "description": description
      };
    }

    if (schemaData) {
      const scriptId = 'json-ld-schema';
      // Corrected: Cast to HTMLScriptElement | null to avoid 'type' property error
      let script = document.getElementById(scriptId) as HTMLScriptElement | null;
      if (script) {
        script.innerHTML = JSON.stringify(schemaData);
      } else {
        const newScript = document.createElement('script');
        newScript.id = scriptId;
        newScript.type = 'application/ld+json';
        newScript.innerHTML = JSON.stringify(schemaData);
        document.head.appendChild(newScript);
      }
    }
  }, [fullTitle, description, resource, resources, type, url]);

  return null; // This component doesn't render anything to the UI
};

export default SEO;

