      // Default Website Schema
      schemaData = {
        "@context": "https://schema.org",
        "@type": "WebSite",
        "name": siteName,
        "url": window.location.origin,
        "description": description
      };
    }

    if (schemaData) {
      const scriptId = 'json-ld-schema';
      // Corrected: Cast the script element to HTMLScriptElement to resolve property access errors on generic HTMLElement.
      const existingScript = document.getElementById(scriptId) as HTMLScriptElement | null;
      if (existingScript) {
        existingScript.innerHTML = JSON.stringify(schemaData);
      } else {
        const newScript = document.createElement('script');
        newScript.id = scriptId;
        newScript.type = 'application/ld+json';
        newScript.innerHTML = JSON.stringify(schemaData);
        document.head.appendChild(newScript);
      }
    }
  }, [fullTitle, description, resource, resources, type, url]);

  return null;
};

